with fun min_reputation() -> integer :
  match $u isa user, has reputation $rep;
  return min($rep);
match
$u isa user, has reputation $rep;
let $min_rep = min_reputation();
$rep == $min_rep;
asked (asker: $u, asked_question: $q);
tagged (tagged_question: $q, tag: $t);
$t has tag_name $tn;
select $tn;
distinct;
fetch { "tag": $tn };

match
$u isa user, has reputation $r;
reduce $max_rep = max($r);
match
$top_user isa user, has reputation $r2;
$r2 == $max_rep;
asked (asker: $top_user, asked_question: $q);
$q has title $title, has text $text, has link $link, has created_at $created;
fetch {
  "question_title": $title,
  "question_text": $text,
  "question_link": $link,
  "created_at": $created
};

match
$u isa user;
asked (asker: $u, asked_question: $q);
$q has down_votes $dv;
$dv == 0;
select $u;
distinct;
fetch {
  "display_name": $u.display_name,
  "user_id": $u.user_id,
  "user_link": $u.user_link
};

match
$q isa question, has favorites $f;
$t isa tag, has tag_name $tn;
tagged (tagged_question: $q, tag: $t);
sort $f desc;
limit 3;
fetch {
  "tag": $tn
};

match
$u isa user;
$q isa question, has up_votes $uv;
$uv == 0;
asked (asker: $u, asked_question: $q);
reduce $count = count($q) groupby $u;
sort $count desc;
limit 3;
fetch {
  "user": $u.display_name,
  "question_count": $count
